#!/usr/bin/expect -f
# Boot goldfish emulator, wait for NSH, verify ai_agent command exists
set timeout 180
set log_user 1

spawn ./emulator.sh vela
# wait for NSH prompt (openvela goldfish)
expect {
    -re {NuttShell \(NSH\)} { send_user "\n>>> NSH detected\n" }
    -re {[vV]ela[>}] } { send_user "\n>>> vela prompt detected\n" }
    timeout { send_user "\n>>> TIMEOUT waiting for NSH\n"; exit 1 }
    eof { send_user "\n>>> EOF before NSH\n"; exit 1 }
}

sleep 3
# check agent command exists
send "ai_agent help\r"
sleep 5
send "ask 现在几点了\r"
sleep 10
send "help\r"
sleep 3
send_user "\n>>> DONE. capture done.\n"
exit 0

